import random
random.seed(20261028)
draws = []
for _ in range(200):
    draws.append(sorted(random.sample(range(1, 71), 5)))
last_seen = {}
for i, d in enumerate(draws):
    for n in d:
        last_seen[n] = i
absence = sorted(((len(draws) - 1 - last_seen.get(n, -1), n) for n in range(1, 71)), reverse=True)
print('SIMULATED draws:', len(draws))
print('most overdue main numbers (gap, number):', absence[:5])
print('numbers never drawn in set:', sum(1 for n in range(1, 71) if n not in last_seen))
